	/** Reclaim without restarting the already-open producer or replacing any pinned backing. */
	boolean reclaimForDecode() throws IOException {
		check(0);
		OptionalMaterialization registry = context == null ? null : context.existingOptionalMaterializations();
		if (registry != null && registry.evictForAdmission()) {
			return true;
		}
		if (directory == null && residentSize != 0) {
			ensureSpill();
			return true;
		}
		return registry != null && registry.reclaimForActiveDecode();
	}

